private int parseEndOfLine(String headerPart, int end) {
    for (int i = end; i < headerPart.length(); i++) {
        char c = headerPart.charAt(i);
        if (c == '\r') {
            i++;
            if (i >= headerPart.length() || headerPart.charAt(i) != '\n') {
                throw new RuntimeException("Invalid header: missing \\n after \\r");
            }
            return i + 1;
        }
    }
    throw new RuntimeException("Invalid header: missing \\r\\n at the end of the line");
}

/**
 * Skips bytes until the end of the current line.
 *
 * @param headerPart The headers, which are being parsed.
 * @param end Index of the last byte, which has yet been processed.
 * @return Index of the \r\n sequence, which indicates end of line.
 */
private int parseEndOfLine(String headerPart, int end) {
    for (int i = end; i < headerPart.length(); i++) {
        if (headerPart.charAt(i) == '\r' && i + 1 < headerPart.length() && headerPart.charAt(i + 1) == '\n') {
            return i + 2;
        }
    }
    return headerPart.length();
}

