public void valueAccumulation (String key, Long value) {
  // Check if the key already exists in the map
  if (!map.containsKey(key)) {
    // If the key does not exist, add it with the given value
    map.put(key, value);
  } else {
    // If the key already exists, accumulate the value to the existing value
    Long existingValue = map.get(key);
    if (existingValue != null) {
      existingValue += value;
    } else {
      map.put(key, value);
    }
  }
}

