public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {

    // Split the box along the x axis into two equal boxes

    // Get the width of the box
    double width = box.getWidth();

    // Calculate the center x-coordinate of the box
    double centerX = box.getCenterX();

    // Calculate the x-coordinate of the new left box
    double leftX = centerX - (width / 2.0);

    // Calculate the x-coordinate of the new right box
    double rightX = centerX + (width / 2.0);

    // Calculate the height of the box
    double height = box.getHeight();

    // Calculate the center y-coordinate of the box
    double centerY = box.getCenterY();

    // Calculate the y-coordinate of the new upper box
    double upperY = centerY - (height / 2.0);

    // Calculate the y-coordinate of the new lower box
    double lowerY = centerY + (height / 2.0);

    // Create and return the two resulting boxes
    return new Pair<>(
            new Box2D(leftX, upperY, width, height),
            new Box2D(rightX, lowerY, width, height)
    );
}

