void putAbstractTypes(int start, int end) {
for (int i = start; i < end; i++) {
stackMapTableEntries.add(new AbstractType(currentFrame.getType(i)));
}
}

public void putAbstractTypes(int start, int end) {
    for (int i = start; i < end; i++) {
        byte tag = getTagForType(currentFrame, i);
        byte[] tagBuf = new byte[] { tag };
        byte[] data = new byte[4];
        data[0] = (byte) (tag >> 2);
        data[1] = (byte) ((tag << 6) >> 8);
        data[2] = (byte) (tag << 4);
        data[3] = 0;
        stackMapTableEntries.put(data, tagBuf);
    }
}

private byte getTagForType(List<AbstractType<?>> frame, int index) {
    AbstractType<?> type = frame.get(index);
    if (type.isUninitializedThis()) {
        return (byte) 0x07;
    }
    if (type.isObjectVariable()) {
        return (byte) 0x72;
    }
    if (type.isNullConstant()) {
        return (byte) 0x00;
    }
    if (type.isUninitialized()) {
        return (byte) 0x0F;
    }
    throw new IllegalArgumentException("Invalid type: " + type);
}

/**
 * Puts some concrete types of  {@link #currentFrame} in {@link #stackMapTableEntries} .
 *
 * @param start index of the first type in {@link #currentFrame} to write.
 * @param end index of last type in {@link #currentFrame} to write (exclusive).
 */
private void putConcreteTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        AbstractType<?> type = currentFrame.get(i);
        if (type.isUninitializedThis()) {
            putByte(0x07);
        } else if (type.isObjectVariable()) {
            putByte(0x72);
        } else if (type.isNullConstant()) {
            putByte(0x00);
        } else if (type.isUninitialized()) {
            putByte(0x0F);
        } else {
            throw new IllegalArgumentException("Invalid type: " + type);
        }
    }
}

/**
 * Puts the offset delta corresponding to the stack map frames in {@link #stackMapTable}.
 *
 * @param delta the offset delta to write.
 */
private void putOffsetDelta(final int delta) {
    if (delta == 0) {
        putByte(0);
    } else {
        putSignedInt(delta);
    }
}

