    // Create a buffer for the unescaped string
    StringBuilder buf = new StringBuilder(str.length());

    // Loop through the characters in the input string
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        // Check for a backslash and escape sequence
        if (c == '\\') {
            // Get the next character in the input string
            char next = str.charAt(i + 1);

            // Check for a valid escape sequence
            if (next == '\\' || next == 'b' || next == 'f' || next == 'n' || next == 'r' || next == 't' || next == '\"' || next == '\'') {
                // Add the escape character to the buffer
                buf.append(next);

                // Skip the escape character and the escaped character
                i++;
                continue;
            }
        }

        // Add the character to the buffer
        buf.append(c);
    }

    // Return the unescaped string
    return buf.toString();
