private Optional<OuterFaceCirculator> selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    Node current = start;
    boolean found = false;

    while (current != stop) {
        if (predicate.test(current)) {
            found = true;
            break;
        }
        current = current.getNext(dir);
    }

    if (found) {
        return Optional.of(new OuterFaceCirculator(current, dir));
    } else {
        return Optional.empty();
    }
}

/**
 * A circulator that iterates over the nodes on the outer face of a given component.
 */
private static class OuterFaceCirculator {
    private Node current;
    private final int dir;

    public OuterFaceCirculator(Node current, int dir) {
        this.current = current;
        this.dir = dir;
    }

    public void circulate() {
        current = current.getNext(dir);
    }

    public boolean hasNext() {
        return current != null;
    }

    public Node next() {
        Node ret = current;
        circulate();
        return ret;
    }
}

/**
* @param predicate the condition the desired node should satisfy
* @param start the node to start the search from
* @param stop the node to end the search with
* @param dir the direction to start the traversal in
* @return a circulator to the node satisfying the {@code predicate} or to the {@code stop} node
*/
private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // find the first node on the outer face that satisfies the predicate
    OuterFaceCirculator circulator = new OuterFaceCirculator(start);
    circulator.setDirection(dir);
    while (circulator.hasNext()) {
        Node current = circulator.next();
        if (predicate.test(current)) {
            return circulator;
        }
    }

    // if no such node is found, return a circulator to the stop node
    circulator.reset();
    return circulator;
}

