    Node current = circulator.current();
    while (!predicate.test(current) && !circulator.atEnd()) {
        if (!circulator.advance()) {
            return circulator;
        }
        current = circulator.current();
    }
    if (circulator.atEnd()) {
        return circulator;
    } else {
        circulator.advance();
