public boolean isShardingKeyIndicesContinuous(String modelName) {
    // Get sharding key indices for the model
    List<Integer> shardingKeyIndices = getShardingKeyIndices(modelName);

    // If there are no sharding keys, return true
    if (shardingKeyIndices.isEmpty()) {
        return true;
    }

    // Set first sharding key index
    Integer previousShardingKeyIndex = shardingKeyIndices.get(0);

    // Check if sharding key indices are continuous
    for (Integer shardingKeyIndex : shardingKeyIndices) {
        if (shardingKeyIndex - previousShardingKeyIndex != 1) {
            return false;
        }
        previousShardingKeyIndex = shardingKeyIndex;
    }

    // If sharding key indices are continuous, return true
    return true;
}

