private List<Pair<Integer,Integer>> computeMinimalSeparators(E edge){
    // Initialize an empty list of pairs, where each pair contains a source and a target node of the edge
    List<Pair<Integer,Integer>> minimalSeparators = new ArrayList<>();

    // Get the source and target nodes of the edge
    int source = graph.getSource(edge);
    int target = graph.getTarget(edge);

    // Check if the source and target nodes are not the same, and if so, add them to the minimal separators list
    if(source != target){
        minimalSeparators.add(new Pair<>(source, target));
    }

    // Iterate over all neighbors of the source and target nodes
    for(int neighbor : graph.neighbors(source)){
        if(neighbor != target){
            // Add the pair of nodes to the minimal separators list
            minimalSeparators.add(new Pair<>(source, neighbor));
        }
    }

    for(int neighbor : graph.neighbors(target)){
        if(neighbor != source){
            minimalSeparators.add(new Pair<>(target, neighbor));
        }
    }

    // Return the list of minimal separators
    return minimalSeparators;
}

