    // Use a list to keep track of all the bounds that have been resolved
    List<Type> resolvedBounds = new ArrayList<>();

    // Get the bounds of the provided type variable
    Type[] bounds = typeVariable.getBounds();

    // Iterate over the bounds
    for (Type bound : bounds) {
        // If the bound is a parameterized type, recursively resolve its bounds
        if (bound instanceof ParameterizedType) {
            resolvedBounds.add(resolveBound((ParameterizedType) bound));
        } else if (bound instanceof TypeVariable) {
            // If the bound is another type variable, recursively resolve its bounds
            resolvedBounds.add(resolveBound((TypeVariable<?>) bound));
        } else {
            // If the bound is not a parameterized type or a type variable, add it to the list
            resolvedBounds.add(bound);
        }
    }

    // Return the first resolved bound, or Unknown.class if none can be resolved
    return resolvedBounds.isEmpty() ? Unknown.class : resolvedBounds.get(0);
}

